<script>
const bakes=[['Sourdough',7.5],['Cardamom bun',3.2],['Rye loaf',8],['Lemon tart',4.5]];
const rows=document.getElementById('rows'),total=document.getElementById('total');
const qty=bakes.map(()=>0);
function render(){
  rows.innerHTML='';
  bakes.forEach(([name,price],i)=>{
    const tr=document.createElement('tr');
    tr.innerHTML=`<td>${name}</td><td>$${price.toFixed(2)}</td><td></td>`;
    const input=document.createElement('input');
    input.type='number';input.min='0';input.value=qty[i];
    input.addEventListener('input',()=>{qty[i]=Math.max(0,parseInt(input.value)||0);sum();});
    tr.lastChild.appendChild(input);
    rows.appendChild(tr);
  });
  sum();
}
function sum(){
  const t=bakes.reduce((s,[,p],i)=>s+p*qty[i],0);
  total.textContent='$'+t.toFixed(2);
}
document.getElementById('suggest').addEventListener('click',()=>{
  const t=document.getElementById('ask').value.trim().toLowerCase();
  const out=document.getElementById('out');
  if(!t){out.textContent='Tell us who you are feeding first.';return;}
  let s='One loaf of sourdough and four lemon tarts cover most gatherings.';
  if(t.includes('six')||t.includes('party')){
    s='For six, get two loaves and a dozen buns.';
  }
  out.textContent=s;
});
render();
</script>

